INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قدر:ibn_durayd_jamharat_lugha', 'قدر', 'ad72daaf5f0460b1e36bd1b5ce', 'وَرجل ذُو قُدرة ومَقْدُرَة ومَقدِرَة، إِذا كَانَ ذَا يسَار', 'a man of means, when well-off', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_9cfcc9f5faf41df1', 0, NULL, 'Marker: «إذا» gloss. Reading: means, ability. Differs from the main reading (measure, amount).', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قدر:jawhari_sihah', 'قدر', 'ad72daaf5f0460b1e36bd1b5ce', 'مبلغه. وقدر الله وقَدْرُهُ بمعنًى', 'its full amount; God''s qadar and qadr are one', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_de2b263a0162aa15', '1560', 2, 'blk_sih_3c11716f41dbf0f0', 0, NULL, 'Marker: head gloss. Reading: amount. Primary: measure, amount — 4 of 10 books (al-Jawharī blk_sih_3c11716f41dbf0f0; Ibn Fāris blk_mqy_cedfb8355bafaa19; al-Miṣbāḥ blk_msb_303e53a3b6c03b91; Lane blk_lane_0bee3dc69cf8246b). Other readings: decree: al-Khalīl, al-Qāmūs, Tāj · power: Ibn Durayd, al-Rāghib, Lisān.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قدر:raghib_mufradat', 'قدر', 'ad72daaf5f0460b1e36bd1b5ce', 'الْقُدْرَةُ إذا وصف بها الإنسان فاسم لهيئة له بها يتمكّن من فعل شيء ما', 'in people, a state that lets them act', 'الراغب الأصفهاني', 'al-Rāghib, al-Mufradāt', 502, 'raghib_mufradat', 're_mfr_28cca0f7e454414c', '657', 1, 'blk_mfr_6602585a81900dd9', 0, NULL, 'Marker: head definition. Reading: power, ability. Differs from the main reading (measure, amount).', 'high', 'active');
