INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قري:ibn_durayd_jamharat_lugha', 'قري', 'f3c7479d875b07ba7839e0c719', 'والقَرْو: مصدر قَروت الأرضَ أقروها قَرْواً، إِذا قطعت أَرضًا إِلَى أُخْرَى ثمَّ أُخْرَى', 'crossing from one land to the next', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_9072975f17cd234c', 0, NULL, 'Marker: head gloss. Reading: going land to land. Differs from the main reading (gathering).', 'medium', 'active');
