INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قري:fayyumi_misbah_munir', 'قري', 'f3c7479d875b07ba7839e0c719', 'قَرَيْتُ الضَّيْفَ أَقْرِيهِ مِنْ بَابِ رَمَى قِرًى بِالْكَسْرِ وَالْقَصْرِ', 'I gave the guest a meal', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_a724cd22eb66c334', '2468', NULL, 'blk_msb_d619e734e6d159d1', 0, NULL, 'Marker: head gloss. Reading: hosting guests. Filed under قرم in this book. Differs from the main reading (gathering).', 'high', 'active');
