INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قري:zabidi_taj_arus', 'قري', 'f3c7479d875b07ba7839e0c719', 'القَرْيَةُ) ، بالفَتْح، وَهِي اللُّغَة المَشْهورَةُ الفُصْحى، (ويُكْسَرُ) ، يمانِيَّةٌ؛ نقلَهُما اللّيْثُ. وقالَ غيرُهُ: الكَسْرُ خَطَأٌ. (المِصْرُ الجامِعُ', 'a town that draws people together', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_471be99b925ccfbd', '282', 39, 'blk_taj_89c59b4024f83d7e', 0, NULL, 'Marker: Qāmūs gloss. Reading: town.', 'high', 'active');
