INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قسط:khalil_kitab_ayn', 'قسط', '0e600e9362a6be613cbbd8e674', 'والقُسُوط: الميل عن الحق', 'turning away from what is right', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_08bfe2e6014c7da5', '1643', NULL, 'blk_kay_e34a487914d76e77', 0, NULL, 'Marker: gloss in entry. Reading: turning from right. Primary: turning from right — 6 of 10 books (al-Khalīl blk_kay_e34a487914d76e77; Ibn Durayd blk_jam_71ca42c8df2a21e3; al-Jawharī blk_sih_b91ee9587714d81d; Ibn Fāris blk_mqy_5bb9ce136afa1610; al-Miṣbāḥ blk_msb_db609d366ac12c04; Lane blk_lane_d2965148fb8bbbf4). Other readings: fairness: Ibn Fāris, al-Rāghib, Lisān, al-Qāmūs, Tāj.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قسط:ibn_durayd_jamharat_lugha', 'قسط', '0e600e9362a6be613cbbd8e674', 'وقَسَطَ الرجلُ، إِذا جَار ؤاقسطَ، إِذا عدل', 'qasaṭa: he did wrong; aqsaṭa: he was fair', 'ابن دريد', 'Ibn Durayd, al-Jamhara', 321, 'ibn_durayd_jamharat_lugha', 're_jam_bba2a268773c7a27', '540', NULL, 'blk_jam_71ca42c8df2a21e3', 0, NULL, 'Marker: «إذا» gloss. Reading: wrong vs fair. Filed under حيي in this book.', 'medium', 'active');
