INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:قسط:lane_lexicon', 'قسط', '0e600e9362a6be613cbbd8e674', 'He declined, or deviated, from the right course; acted unjustly, wrongfully, injuriously, or tyrannically.', 'he left the right way, acted unjustly', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_9f29bf9f7b6dca44', '2522', NULL, 'blk_lane_d2965148fb8bbbf4', 0, NULL, 'Marker: first sense A1. Reading: acting unjustly.', 'high', 'active');
UPDATE ar_ling_root_asl SET note_md = trim(CASE WHEN instr(coalesce(note_md,''),'Primary:') > 0 THEN substr(note_md, 1, instr(note_md,'Primary:') - 1) ELSE coalesce(note_md,'') END) || ' ' || 'Reading: fairness, turning from right.', updated_at = datetime('now') WHERE id = 'ASL:قسط:maqayis_lugha' AND coalesce(note_md,'') NOT LIKE '%Reading:%';
